import { mkdir, readdir, readFile, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { pathToFileURL } from 'node:url';
import esbuild from 'esbuild';

import {
  REQUIRED_METADATA_FIELDS,
  extractMetadataBlockText,
  firstMetadataValue,
  parseMetadataBlock,
} from './lib/userscript-metadata.mjs';

const GENERATED_NOTE = (scriptId) => [
  '// GENERATED by scripts/build-userscripts.mjs — do not edit by hand.',
  `// Sources: src/userscripts/${scriptId}/ (rebuild with \`npm run build\`).`,
].join('\n');

async function discoverEntries(rootDir) {
  const userscriptsDir = path.join(rootDir, 'src', 'userscripts');
  const entries = [];
  for (const dirent of await readdir(userscriptsDir, { withFileTypes: true })) {
    if (!dirent.isDirectory()) continue;
    const scriptId = dirent.name;
    const entryPath = path.join(userscriptsDir, scriptId, `${scriptId}.entry.js`);
    try {
      await readFile(entryPath, 'utf8');
      entries.push({ scriptId, entryPath, scriptDir: path.join(userscriptsDir, scriptId) });
    } catch {
      // No entry module: plain single-file userscript directory, nothing to build.
    }
  }
  return entries;
}

function validateEntryMetadata({ scriptId, entryPath, entrySource }) {
  const metadataText = extractMetadataBlockText(entrySource);
  const metadata = metadataText ? parseMetadataBlock(entrySource) : null;
  if (!metadataText || !metadata) {
    throw new Error(`${entryPath}: missing userscript metadata block`);
  }

  for (const field of REQUIRED_METADATA_FIELDS) {
    if (!metadata.has(field)) {
      throw new Error(`${entryPath}: missing ${field}`);
    }
  }

  if (metadata.has('@require')) {
    throw new Error(`${entryPath}: @require is not allowed in bundled entries — use ESM imports instead`);
  }

  const expectedSuffix = `/dist/${scriptId}.user.js`;
  for (const field of ['@downloadURL', '@updateURL']) {
    const value = firstMetadataValue(metadata, field);
    if (!value.endsWith(expectedSuffix)) {
      throw new Error(`${entryPath}: ${field} must point at ${expectedSuffix} (got "${value}")`);
    }
  }

  const version = firstMetadataValue(metadata, '@version');
  const scriptVersionMatch = entrySource.match(/const SCRIPT_VERSION = '([^']+)'/);
  if (scriptVersionMatch && scriptVersionMatch[1] !== version) {
    throw new Error(
      `${entryPath}: SCRIPT_VERSION "${scriptVersionMatch[1]}" does not match @version "${version}"`,
    );
  }

  return { metadataText, metadata };
}

async function assertNoOrphanLibs({ rootDir, scriptDir, entryPath, metafile }) {
  const bundledInputs = new Set(
    Object.keys(metafile.inputs).map((input) => path.resolve(rootDir, input)),
  );
  const libFiles = (await readdir(scriptDir)).filter((name) => name.endsWith('.lib.js'));
  const orphans = libFiles.filter((name) => !bundledInputs.has(path.join(scriptDir, name)));
  if (orphans.length) {
    throw new Error(
      `${entryPath}: orphan lib file(s) not reachable from the entry module graph: ${orphans.join(', ')}`,
    );
  }
}

function bridgeStub({ scriptId, metadataText, metadata }) {
  const name = firstMetadataValue(metadata, '@name') || scriptId;
  const downloadUrl = firstMetadataValue(metadata, '@downloadURL');
  return [
    metadataText,
    GENERATED_NOTE(scriptId),
    '// Bridge stub: keeps the legacy install path alive for update discovery only.',
    '(function () {',
    "  'use strict';",
    `  console.info('${name}: this legacy path is a bridge stub — install the real script from ${downloadUrl}');`,
    '})();',
    '',
  ].join('\n');
}

export async function buildAll({ rootDir = process.cwd(), distDir = path.join(rootDir, 'dist') } = {}) {
  const targets = await discoverEntries(rootDir);
  const results = [];

  for (const { scriptId, entryPath, scriptDir } of targets) {
    const entrySource = await readFile(entryPath, 'utf8');
    const { metadataText, metadata } = validateEntryMetadata({ scriptId, entryPath, entrySource });

    const buildResult = await esbuild.build({
      entryPoints: [entryPath],
      bundle: true,
      format: 'iife',
      platform: 'browser',
      target: 'es2022',
      minify: false,
      charset: 'utf8',
      sourcemap: false,
      write: false,
      metafile: true,
      absWorkingDir: rootDir,
      logLevel: 'silent',
    });
    await assertNoOrphanLibs({ rootDir, scriptDir, entryPath, metafile: buildResult.metafile });

    const bundledCode = buildResult.outputFiles[0].text;
    const distPath = path.join(distDir, `${scriptId}.user.js`);
    const bridgePath = path.join(scriptDir, `${scriptId}.user.js`);

    await mkdir(distDir, { recursive: true });
    await writeFile(distPath, `${metadataText}\n${GENERATED_NOTE(scriptId)}\n${bundledCode}`);
    await writeFile(bridgePath, bridgeStub({ scriptId, metadataText, metadata }));

    results.push({ scriptId, distPath, bridgePath });
  }

  return results;
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  const results = await buildAll({});
  if (!results.length) {
    console.log('Nothing to build: no <script-id>.entry.js modules found under src/userscripts/.');
  } else {
    for (const { scriptId, distPath } of results) {
      console.log(`Built ${scriptId} -> ${path.relative(process.cwd(), distPath)}`);
    }
  }
}
